insert into articles (id, author_id, created_at, image_url, headline, sub, flash, body, prev_id) values
  ('m1', 'mom', now() - interval '1 hours', 'data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22800%22%20height%3D%22600%22%3E%3Cdefs%3E%3Cpattern%20id%3D%22p%22%20width%3D%2216%22%20height%3D%2216%22%20patternUnits%3D%22userSpaceOnUse%22%20patternTransform%3D%22rotate(45)%22%3E%3Crect%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23e6dfd1%22%2F%3E%3Crect%20x%3D%228%22%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23ddd5c5%22%2F%3E%3C%2Fpattern%3E%3C%2Fdefs%3E%3Crect%20width%3D%22800%22%20height%3D%22600%22%20fill%3D%22url(%23p)%22%2F%3E%3Ctext%20x%3D%22400%22%20y%3D%22310%22%20font-family%3D%22monospace%22%20font-size%3D%2228%22%20fill%3D%22%236f665a%22%20text-anchor%3D%22middle%22%3Elemon%20tree%20photo%3C%2Ftext%3E%3C%2Fsvg%3E', 'עונת הלימונים נפתחה: העץ בחצר של רינה הניב את הפרי הראשון', '"שלוש שנים חיכיתי לו", היא מספרת. הלימון הראשון נקטף ביום ראשון בבוקר', 'הלימון הראשון נקטף מהעץ בחצר של רינה כהן', array['שלוש שנים אחרי שנשתל, עץ הלימון בחצר של רינה הניב סוף סוף פרי. את השתיל קנתה במשתלה ליד הבית, ומאז השקתה אותו כמעט כל בוקר, גם בחורפים שבהם נראה שהוא לא מתכוון לגדול.', '"שלוש שנים חיכיתי לו", מספרת רינה. "בשנה הראשונה היו רק עלים. בשנה השנייה הופיעו פרחים ונשרו. השנה, באמצע הקיץ, ראיתי פתאום כדור ירוק קטן בין העלים ולא אמרתי לאף אחד, שלא אפספס את המזל".', 'הלימון הבשיל לאט, הצהיב במשך כמה שבועות, ונקטף ביום ראשון בבוקר. רינה צילמה אותו מכל זווית לפני שהעזה להוריד אותו מהענף.', '"קטפתי אותו ביום ראשון בבוקר ועוד לא החלטתי מה לעשות איתו", היא אומרת. "אולי לימונדה, אולי עוגה. בינתיים הוא יושב על השולחן במטבח ואני מסתכלת עליו".']::text[], null),
  ('orit0', 'orit', now() - interval '168 hours', 'data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22800%22%20height%3D%22600%22%3E%3Cdefs%3E%3Cpattern%20id%3D%22p%22%20width%3D%2216%22%20height%3D%2216%22%20patternUnits%3D%22userSpaceOnUse%22%20patternTransform%3D%22rotate(45)%22%3E%3Crect%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23e6dfd1%22%2F%3E%3Crect%20x%3D%228%22%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23ddd5c5%22%2F%3E%3C%2Fpattern%3E%3C%2Fdefs%3E%3Crect%20width%3D%22800%22%20height%3D%22600%22%20fill%3D%22url(%23p)%22%2F%3E%3Ctext%20x%3D%22400%22%20y%3D%22310%22%20font-family%3D%22monospace%22%20font-size%3D%2228%22%20fill%3D%22%236f665a%22%20text-anchor%3D%22middle%22%3Eold%20diaries%20photo%3C%2Ftext%3E%3C%2Fsvg%3E', 'בין ארגזי המעבר: אורית מצאה את יומני המטבח של סבתה', 'היא עברה על האלבומים הישנים ועל מה שנשאר לפני המעבר לדירה החדשה. "בין התמונות היה יומן עם כתב היד שלה"', 'אורית מצאה את יומני המטבח של סבתה בזמן מעבר דירה', array['לקראת המעבר לדירה החדשה, אורית ישבה כמה ערבים ברצף על רצפת הסלון, מוקפת בארגזים. רובם היו מלאים בכלים ובספרים, אבל שניים מהם היו של סבתה: אלבומים ישנים, מכתבים, וכל מה שנשאר אחריה ואף אחד לא העז לזרוק.', '"התחלתי לעבור על האלבומים כדי להחליט מה לוקחים ומה לא", היא מספרת. "ובין התמונות היה יומן קטן, עם כריכה חומה, עם כתב היד שלה. ישר זיהיתי את הכתב".', 'היומן התגלה כיומן מטבח: רשימות קניות, הערות על ארוחות שבת, ומתכונים שנכתבו בלי כמויות מדויקות, רק "כוס בערך" ו"עד שזה מרגיש נכון". "בעמוד אחד היה כתוב בכותרת: עוגת שמרים, לשבת", אומרת אורית. "את העוגה הזאת אני זוכרת מכל ביקור אצלה".', 'היומן לא נכנס לארגז. אורית שמה אותו בתיק, יחד עם המסמכים החשובים, והחליטה שהדבר הראשון שתאפה בדירה החדשה, אחרי שתסיים לפרוק, יהיה העוגה מהעמוד הזה.']::text[], null),
  ('orit1', 'orit', now() - interval '2 hours', 'data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22800%22%20height%3D%22600%22%3E%3Cdefs%3E%3Cpattern%20id%3D%22p%22%20width%3D%2216%22%20height%3D%2216%22%20patternUnits%3D%22userSpaceOnUse%22%20patternTransform%3D%22rotate(45)%22%3E%3Crect%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23e6dfd1%22%2F%3E%3Crect%20x%3D%228%22%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23ddd5c5%22%2F%3E%3C%2Fpattern%3E%3C%2Fdefs%3E%3Crect%20width%3D%22800%22%20height%3D%22600%22%20fill%3D%22url(%23p)%22%2F%3E%3Ctext%20x%3D%22400%22%20y%3D%22310%22%20font-family%3D%22monospace%22%20font-size%3D%2228%22%20fill%3D%22%236f665a%22%20text-anchor%3D%22middle%22%3Eyeast%20cake%20photo%3C%2Ftext%3E%3C%2Fsvg%3E', 'המתכון מהיומן של סבתא שוחזר: אורית אפתה עוגת שמרים לראשונה', 'שבוע אחרי שמצאה את היומן בארגזי המעבר, הבצק תפח במטבח החדש. "בדיוק כמו שהיא תיארה"', 'אורית אפתה לראשונה את עוגת השמרים מהיומן של סבתה', array['שבוע אחרי שמצאה את יומן המטבח של סבתה בין ארגזי המעבר, אורית פינתה סוף סוף את השיש במטבח החדש. חלק מהארגזים עדיין עומדים בחדר השינה, אבל הקמח, השמרים והתבנית כבר מצאו את מקומם.', 'המתכון כתוב בכתב יד, בלי כמויות מדויקות ועם כמה מילים שכמעט נמחקו. "הייתי צריכה לנחש בחלק מהשלבים", היא מספרת. "כשהיה כתוב ״להוסיף קמח עד שהבצק מפסיק להידבק״, פשוט עמדתי והוספתי בכפית".', 'הבצק נח שעתיים על אדן החלון. "הבצק תפח בדיוק כמו שהיא תיארה", סיפרה אורית. "כשהריח התחיל להתפשט בדירה, זה היה הרגע הראשון שהדירה באמת הרגישה לי כמו בית".', 'העוגה הראשונה שנאפתה בדירה החדשה נגמרה עוד באותו ערב. את היומן החזירה אורית למדף במטבח, פתוח בעמוד של העוגה, ליד ספרי הבישול. "יש שם עוד הרבה מתכונים", היא אומרת. "זה רק הראשון".']::text[], 'orit0'),
  ('m2', 'shachar', now() - interval '3 hours', 'data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22800%22%20height%3D%22600%22%3E%3Cdefs%3E%3Cpattern%20id%3D%22p%22%20width%3D%2216%22%20height%3D%2216%22%20patternUnits%3D%22userSpaceOnUse%22%20patternTransform%3D%22rotate(45)%22%3E%3Crect%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23e6dfd1%22%2F%3E%3Crect%20x%3D%228%22%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23ddd5c5%22%2F%3E%3C%2Fpattern%3E%3C%2Fdefs%3E%3Crect%20width%3D%22800%22%20height%3D%22600%22%20fill%3D%22url(%23p)%22%2F%3E%3Ctext%20x%3D%22400%22%20y%3D%22310%22%20font-family%3D%22monospace%22%20font-size%3D%2228%22%20fill%3D%22%236f665a%22%20text-anchor%3D%22middle%22%3Egym%20photo%3C%2Ftext%3E%3C%2Fsvg%3E', 'שיא אישי בחדר הכושר: שחר הרים 100 קילו בסקוואט', 'אחרי חודשים של אימונים בשש בבוקר, הרגע הגיע ביום שלישי. "הסתכלתי על המשקולות ולא האמנתי"', 'שחר לוי שבר שיא אישי בסקוואט: 100 ק"ג', array['אחרי חודשים של אימונים בשש בבוקר, הרגע הגיע ביום שלישי. שחר עמד מול המוט עם 100 קילו, המספר שסימן לעצמו כיעד עוד בתחילת השנה.', 'את המסלול לשם עשה בהדרגה: עוד חמישה קילו כל כמה שבועות, ותקופות שבהן לא התקדם בכלל. "היו שבועות שהרגשתי שאני תקוע על אותו משקל לנצח", הוא מספר. "המאמן כל הזמן אמר לי לא למהר".', 'ביום שלישי, אחרי חימום רגיל, המאמן הציע לנסות. שחר ירד, עצר לשנייה בתחתית ועלה. "הסתכלתי על המשקולות ולא האמנתי", אמר. "רק כשכולם בחדר מחאו כפיים הבנתי שזה באמת קרה".', 'את היעד הבא הוא עוד לא קבע. "בינתיים אני נהנה מזה", הוא אומר. "ומחר בשש בבוקר אני שוב שם".']::text[], null),
  ('m3', 'roni', now() - interval '24 hours', 'data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22800%22%20height%3D%22600%22%3E%3Cdefs%3E%3Cpattern%20id%3D%22p%22%20width%3D%2216%22%20height%3D%2216%22%20patternUnits%3D%22userSpaceOnUse%22%20patternTransform%3D%22rotate(45)%22%3E%3Crect%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23e6dfd1%22%2F%3E%3Crect%20x%3D%228%22%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23ddd5c5%22%2F%3E%3C%2Fpattern%3E%3C%2Fdefs%3E%3Crect%20width%3D%22800%22%20height%3D%22600%22%20fill%3D%22url(%23p)%22%2F%3E%3Ctext%20x%3D%22400%22%20y%3D%22310%22%20font-family%3D%22monospace%22%20font-size%3D%2228%22%20fill%3D%22%236f665a%22%20text-anchor%3D%22middle%22%3Esofa%20photo%3C%2Ftext%3E%3C%2Fsvg%3E', 'אחרי שלושה שבועות על כריות: לדירה של רוני הגיעה ספה', 'המשלוח התעכב פעמיים, והשליח נתקע במעלית. "התיישבנו עליה עוד לפני שהורדנו את הניילון"', 'הספה הגיעה לדירה של רוני אחרי שני עיכובים', array['אחרי שלושה שבועות שבהם ישבה על כריות על הרצפה, לדירה של רוני הגיעה סוף סוף ספה. ההזמנה בוצעה כבר בתחילת החודש, אבל המשלוח התעכב פעמיים, בכל פעם עם הודעה אחרת מהחברה.', 'כשהגיע היום, השליח נתקע במעלית בין הקומה השלישית לרביעית, עם הספה בפנים. "עמדתי בחדר המדרגות ושמעתי אותו מדבר בטלפון עם הטכנאי", מספרת רוני. "חשבתי שזה אולי סימן שאני אמורה לשבת על כריות לתמיד".', 'אחרי חצי שעה המעלית זזה, והספה נכנסה לסלון בלי שריטה. "התיישבנו עליה עוד לפני שהורדנו את הניילון", סיפרה רוני.', 'הכריות לא נזרקו. הן עברו לפינה, ורוני אומרת שהן יחכו שם לאורחים. "אבל לא אני", היא מוסיפה. "אני כבר לא יורדת מהספה".']::text[], null),
  ('m4', 'dad', now() - interval '24 hours', 'data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22800%22%20height%3D%22600%22%3E%3Cdefs%3E%3Cpattern%20id%3D%22p%22%20width%3D%2216%22%20height%3D%2216%22%20patternUnits%3D%22userSpaceOnUse%22%20patternTransform%3D%22rotate(45)%22%3E%3Crect%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23e6dfd1%22%2F%3E%3Crect%20x%3D%228%22%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23ddd5c5%22%2F%3E%3C%2Fpattern%3E%3C%2Fdefs%3E%3Crect%20width%3D%22800%22%20height%3D%22600%22%20fill%3D%22url(%23p)%22%2F%3E%3Ctext%20x%3D%22400%22%20y%3D%22310%22%20font-family%3D%22monospace%22%20font-size%3D%2228%22%20fill%3D%22%236f665a%22%20text-anchor%3D%22middle%22%3Emorning%20walk%20photo%3C%2Ftext%3E%3C%2Fsvg%3E', '14 ימים ברצף: דני ממשיך בהליכת הבוקר', 'ההרגל התחיל אחרי בדיקה שגרתית. "בהתחלה זה היה עונש, עכשיו אני מחכה לזה"', 'דני כהן השלים שבועיים רצופים של הליכות בוקר', array['ההרגל התחיל אחרי בדיקה שגרתית אצל הרופא, שהמליץ לדני להוסיף קצת תנועה ליום. דני החליט להתחיל בהליכה של חצי שעה, כל בוקר, לפני העבודה.', '"בהתחלה זה היה עונש", הוא מודה. "השעון צלצל, בחוץ עוד היה חושך, ואני חיפשתי כל תירוץ להישאר במיטה. ביום השלישי כמעט ויתרתי".', 'עם הזמן נקבע מסלול קבוע: סביב הפארק, ליד המאפייה, וחזרה הביתה. הוא התחיל להכיר את הפנים של מי שהולך באותה שעה, ואת המוכר במאפייה שכבר מנופף לו מבפנים.', 'הבוקר השלים דני 14 ימים ברצף. "עכשיו אני מחכה לזה", הוא אומר. "אם אני מפספס יום, זה מרגיש כאילו משהו חסר".']::text[], null),
  ('m5', 'tamar', now() - interval '48 hours', 'data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22800%22%20height%3D%22600%22%3E%3Cdefs%3E%3Cpattern%20id%3D%22p%22%20width%3D%2216%22%20height%3D%2216%22%20patternUnits%3D%22userSpaceOnUse%22%20patternTransform%3D%22rotate(45)%22%3E%3Crect%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23e6dfd1%22%2F%3E%3Crect%20x%3D%228%22%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23ddd5c5%22%2F%3E%3C%2Fpattern%3E%3C%2Fdefs%3E%3Crect%20width%3D%22800%22%20height%3D%22600%22%20fill%3D%22url(%23p)%22%2F%3E%3Ctext%20x%3D%22400%22%20y%3D%22310%22%20font-family%3D%22monospace%22%20font-size%3D%2228%22%20fill%3D%22%236f665a%22%20text-anchor%3D%22middle%22%3Eoffice%20plant%20photo%3C%2Ftext%3E%3C%2Fsvg%3E', 'הפיקוס במשרד הוציא עלה חדש: "הוא היה על סף מוות"', 'תמר אימצה את העציץ הנטוש בפינת המטבחון. שלושה חודשים של השקיה ראו פרי', 'עלה חדש בפיקוס של המשרד', array['כשתמר הגיעה לעבודה במשרד, הפיקוס בפינת המטבחון כבר היה שם, צהוב ומאובק, עם שלושה עלים אחרונים. אף אחד לא זכר מי הביא אותו, ואף אחד לא השקה אותו.', 'תמר אימצה את העציץ. היא העבירה אותו קרוב יותר לחלון, ניקתה את העלים, ותלתה על דלת המקרר פתק עם תאריכי השקיה. "כמה אנשים צחקו עליי", היא מספרת. "אמרו שאני מבזבזת את הזמן על צמח מת".', 'שלושה חודשים של השקיה פעם בשבוע, ובשבוע שעבר הופיע עלה חדש, ירוק ומבריק. "הוא היה על סף מוות", היא אומרת. "עכשיו יש לו עלה חדש, ואני בודקת אותו כל בוקר".', 'מאז הופעת העלה, לפי תמר, יש במשרד עוד שני אנשים ששואלים מתי תורם להשקות.']::text[], null),
  ('m7', 'shachar', now() - interval '72 hours', 'data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22800%22%20height%3D%22600%22%3E%3Cdefs%3E%3Cpattern%20id%3D%22p%22%20width%3D%2216%22%20height%3D%2216%22%20patternUnits%3D%22userSpaceOnUse%22%20patternTransform%3D%22rotate(45)%22%3E%3Crect%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23e6dfd1%22%2F%3E%3Crect%20x%3D%228%22%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23ddd5c5%22%2F%3E%3C%2Fpattern%3E%3C%2Fdefs%3E%3Crect%20width%3D%22800%22%20height%3D%22600%22%20fill%3D%22url(%23p)%22%2F%3E%3Ctext%20x%3D%22400%22%20y%3D%22310%22%20font-family%3D%22monospace%22%20font-size%3D%2228%22%20fill%3D%22%236f665a%22%20text-anchor%3D%22middle%22%3Etv%20photo%3C%2Ftext%3E%3C%2Fsvg%3E', 'סוף עידן: שחר סיים את הסדרה שליוותה אותו מאז הקיץ', 'שש עונות, ארבעה חודשים ופרק אחרון אחד. "אני לא יודע מה לעשות עם הערבים שלי"', 'שחר לוי סיים לצפות בסדרה אחרי ארבעה חודשים', array['שש עונות, ארבעה חודשים ופרק אחרון אחד. שחר התחיל לצפות בסדרה בתחילת הקיץ, אחרי שחבר המליץ, והתכוון לראות רק פרק אחד כדי להבין על מה כולם מדברים.', 'מהר מאוד זה הפך לטקס קבוע: פרק או שניים כל ערב, אחרי האימון והמקלחת. בסופי שבוע, לפעמים יותר. "היו לילות שאמרתי עוד פרק אחד, ופתאום היה אחת בלילה", הוא מספר.', 'את הפרק האחרון ראה ביום ראשון בלילה, לבד בסלון. כשהכתוביות עלו הוא נשאר לשבת עוד כמה דקות מול המסך השחור.', '"אני לא יודע מה לעשות עם הערבים שלי", אמר שחר. "החברים כבר שולחים לי המלצות לסדרה הבאה, אבל אני מרגיש שאני צריך קצת זמן להתאבל".']::text[], null),
  ('m8', 'yossi', now() - interval '96 hours', 'data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22800%22%20height%3D%22600%22%3E%3Cdefs%3E%3Cpattern%20id%3D%22p%22%20width%3D%2216%22%20height%3D%2216%22%20patternUnits%3D%22userSpaceOnUse%22%20patternTransform%3D%22rotate(45)%22%3E%3Crect%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23e6dfd1%22%2F%3E%3Crect%20x%3D%228%22%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23ddd5c5%22%2F%3E%3C%2Fpattern%3E%3C%2Fdefs%3E%3Crect%20width%3D%22800%22%20height%3D%22600%22%20fill%3D%22url(%23p)%22%2F%3E%3Ctext%20x%3D%22400%22%20y%3D%22310%22%20font-family%3D%22monospace%22%20font-size%3D%2228%22%20fill%3D%22%236f665a%22%20text-anchor%3D%22middle%22%3Eparking%20photo%3C%2Ftext%3E%3C%2Fsvg%3E', 'נס בחניון: יוסי מצא חניה ליד הכניסה ביום ראשון בבוקר', 'לראשונה מאז שהתחיל לעבוד בבניין, החניה הראשונה הייתה פנויה. "חשבתי שזו מלכודת"', 'חניה פנויה ליד הכניסה, לראשונה מזה שנה', array['כבר יותר משנה שיוסי עובד באותו בניין, ובכל אותה שנה החניה הראשונה, זו שליד הכניסה, הייתה תפוסה. לא משנה באיזו שעה הגיע, תמיד עמד שם רכב.', 'ביום ראשון בבוקר, כשנכנס לחניון, הוא ראה אותה ריקה. "חשבתי שזו מלכודת", הודה יוסי. "הסתכלתי אם יש שלט, אם מישהו עומד לחזור, אם יש שם שמן על הרצפה. לא היה כלום".', 'הוא חנה, נשאר עוד רגע ברכב, ואז צילם את הרכב שלו במקום. את התמונה שלח לכמה חברים מהעבודה עוד לפני שעלה למשרד.', 'בסוף היום, כשיצא, כבר חיכה לידו רכב אחר שרצה את המקום. "אני לא יודע אם זה יקרה שוב", אומר יוסי. "אבל לפחות יש לי הוכחה שזה אפשרי".']::text[], null),
  ('mx', 'maya', now() - interval '120 hours', 'data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22800%22%20height%3D%22600%22%3E%3Cdefs%3E%3Cpattern%20id%3D%22p%22%20width%3D%2216%22%20height%3D%2216%22%20patternUnits%3D%22userSpaceOnUse%22%20patternTransform%3D%22rotate(45)%22%3E%3Crect%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23e6dfd1%22%2F%3E%3Crect%20x%3D%228%22%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23ddd5c5%22%2F%3E%3C%2Fpattern%3E%3C%2Fdefs%3E%3Crect%20width%3D%22800%22%20height%3D%22600%22%20fill%3D%22url(%23p)%22%2F%3E%3Ctext%20x%3D%22400%22%20y%3D%22310%22%20font-family%3D%22monospace%22%20font-size%3D%2228%22%20fill%3D%22%236f665a%22%20text-anchor%3D%22middle%22%3Ewhite%20shirt%20photo%3C%2Ftext%3E%3C%2Fsvg%3E', 'אחרי חודש של מבטים בחלון הראווה: מאיה קנתה את החולצה הלבנה', '"כל יום עברתי שם בדרך מהעבודה ובדקתי שהיא עדיין שם", היא מספרת', 'מאיה כהן קנתה סוף סוף את החולצה הלבנה מהחלון', array['במשך חודש עברה מאיה כמעט כל יום מול חלון הראווה של החנות ברחוב הראשי, בדרך מהעבודה לתחנת האוטובוס. בחלון, על בובה בלי ראש, הייתה תלויה חולצה לבנה ומכופתרת.', '"כל יום עברתי שם ובדקתי שהיא עדיין שם", היא מספרת. "בהתחלה רק הסתכלתי. אחרי שבוע כבר נכנסתי לבדוק מידות, ויצאתי בלי כלום. אמרתי לעצמי שאם היא תחכה לי עד סוף החודש, זה סימן".', 'החולצה חיכתה. ביום חמישי, אחרי יום עבודה ארוך, מאיה נכנסה לחנות, ביקשה את המידה שלה והלכה ישר לקופה, בלי למדוד שוב. "המוכרת שאלה אם אני בטוחה. אמרתי לה שאני בטוחה כבר חודש".', 'את החולצה היא מתכננת ללבוש לראשונה כבר בשבוע הבא, במשרד. "אני יודעת שלבן זה מסוכן", היא מודה, "אבל אני אזהר".']::text[], null),
  ('maya', 'maya', now() - interval '0.05 hours', null, 'למזלה זה לא קרה: האסון נמנע – הטחינה כמעט עשתה בלגן בעבודה', 'בהפסקת הצהריים במשרד נשפך רוטב הטחינה על הרצפה, סנטימטרים ספורים מהחולצה החדשה של מאיה. "אחרת הייתי מתחרפנת", היא מספרת', 'חדר האוכל במשרד: רוטב טחינה נשפך על הרצפה, החולצה החדשה של מאיה יצאה ללא פגע', array['זה היה אמור להיות עוד צהריים רגילים במשרד. מאיה, בת 29 מרמת גן ומזכירה בחברת ביטוח, ישבה בחדר האוכל עם שאריות מארוחת הערב של אתמול: שווארמה, המאכל האהוב עליה, ואורז. ואז רוטב הטחינה נשפך על הרצפה, ממש ליד החולצה החדשה שלה.', 'את החולצה, לבנה ומכופתרת, קנתה מאיה רק בשבוע שעבר, אחרי חודש שבו עברה מול חלון הראווה כמעט כל יום.', '"אני אוכלת צהריים במשרד וכמעט שפכתי עליי רוטב טחינה. למזלי זה לא קרה, אחרת הייתי מתחרפנת", סיפרה מאיה.', 'כשנשאלה מה היה קורה אילו התרחיש הגרוע היה מתממש, היא לא היססה: "כנראה הייתי צוחקת מבושה, רצה לשירותים לבכות, ואז שואלת בקבוצה של הבנות אם למישהי יש חולצה להחליף".', 'בסופו של דבר הטחינה נשארה על הרצפה, והחולצה נשארה נקייה.']::text[], 'mx'),
  ('t1', 'dalia', now() - interval '2 hours', 'data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22800%22%20height%3D%22600%22%3E%3Cdefs%3E%3Cpattern%20id%3D%22p%22%20width%3D%2216%22%20height%3D%2216%22%20patternUnits%3D%22userSpaceOnUse%22%20patternTransform%3D%22rotate(45)%22%3E%3Crect%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23e6dfd1%22%2F%3E%3Crect%20x%3D%228%22%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23ddd5c5%22%2F%3E%3C%2Fpattern%3E%3C%2Fdefs%3E%3Crect%20width%3D%22800%22%20height%3D%22600%22%20fill%3D%22url(%23p)%22%2F%3E%3Ctext%20x%3D%22400%22%20y%3D%22310%22%20font-family%3D%22monospace%22%20font-size%3D%2228%22%20fill%3D%22%236f665a%22%20text-anchor%3D%22middle%22%3Eceramic%20vase%20photo%3C%2Ftext%3E%3C%2Fsvg%3E', 'מהסדנה אל המדף: דליה סיימה את האגרטל הירוק שעבדה עליו חודש', 'שלוש שכבות זיגוג, שריפה אחת ארוכה ותוצאה שהפתיעה גם אותה. "לא חשבתי שהירוק ייצא כל כך עמוק"', 'דליה גולן סיימה אגרטל קרמיקה חדש בסדנה', array['במשך חודש עבדה דליה על האגרטל בסדנה, שכבה אחרי שכבה. היא הגיעה פעמיים בשבוע, אחרי העבודה, ובכל פעם הוסיפה עוד קצת, תיקנה, החליקה.', 'את הצבע בחרה מראש: ירוק עמוק, כמו של העלים בגינה של ההורים שלה. כדי להגיע אליו מרחה שלוש שכבות זיגוג, וחיכתה לשריפה אחת ארוכה בתנור של הסדנה. "המורה אמרה לי שעם ירוק אף פעם אי אפשר לדעת מה ייצא", היא מספרת.', '"לא חשבתי שהירוק ייצא כל כך עמוק", אמרה דליה. "כשפתחתי את התנור פשוט עמדתי והסתכלתי. כולם בסדנה באו לראות".', 'האגרטל עומד עכשיו על המדף בסלון, בינתיים בלי פרחים. "אני עוד לא רוצה להסתיר אותו", היא אומרת.']::text[], null),
  ('t3', 'yossi', now() - interval '96 hours', 'data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22800%22%20height%3D%22600%22%3E%3Cdefs%3E%3Cpattern%20id%3D%22p%22%20width%3D%2216%22%20height%3D%2216%22%20patternUnits%3D%22userSpaceOnUse%22%20patternTransform%3D%22rotate(45)%22%3E%3Crect%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23e6dfd1%22%2F%3E%3Crect%20x%3D%228%22%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23ddd5c5%22%2F%3E%3C%2Fpattern%3E%3C%2Fdefs%3E%3Crect%20width%3D%22800%22%20height%3D%22600%22%20fill%3D%22url(%23p)%22%2F%3E%3Ctext%20x%3D%22400%22%20y%3D%22310%22%20font-family%3D%22monospace%22%20font-size%3D%2228%22%20fill%3D%22%236f665a%22%20text-anchor%3D%22middle%22%3Eparking%20photo%3C%2Ftext%3E%3C%2Fsvg%3E', 'נס בחניון: יוסי מצא חניה ליד הכניסה ביום ראשון בבוקר', 'לראשונה מאז שהתחיל לעבוד בבניין, החניה הראשונה הייתה פנויה. "חשבתי שזו מלכודת"', 'חניה פנויה ליד הכניסה, לראשונה מזה שנה', array['כבר יותר משנה שיוסי עובד באותו בניין, ובכל אותה שנה החניה הראשונה, זו שליד הכניסה, הייתה תפוסה. לא משנה באיזו שעה הגיע, תמיד עמד שם רכב.', 'ביום ראשון בבוקר, כשנכנס לחניון, הוא ראה אותה ריקה. "חשבתי שזו מלכודת", הודה יוסי. "הסתכלתי אם יש שלט, אם מישהו עומד לחזור, אם יש שם שמן על הרצפה. לא היה כלום".', 'הוא חנה, נשאר עוד רגע ברכב, ואז צילם את הרכב שלו במקום. את התמונה שלח לכמה חברים מהעבודה עוד לפני שעלה למשרד.', 'בסוף היום, כשיצא, כבר חיכה לידו רכב אחר שרצה את המקום. "אני לא יודע אם זה יקרה שוב", אומר יוסי. "אבל לפחות יש לי הוכחה שזה אפשרי".']::text[], null),
  ('tm1', 'tamir', now() - interval '24 hours', 'data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22800%22%20height%3D%22600%22%3E%3Cdefs%3E%3Cpattern%20id%3D%22p%22%20width%3D%2216%22%20height%3D%2216%22%20patternUnits%3D%22userSpaceOnUse%22%20patternTransform%3D%22rotate(45)%22%3E%3Crect%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23e6dfd1%22%2F%3E%3Crect%20x%3D%228%22%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23ddd5c5%22%2F%3E%3C%2Fpattern%3E%3C%2Fdefs%3E%3Crect%20width%3D%22800%22%20height%3D%22600%22%20fill%3D%22url(%23p)%22%2F%3E%3Ctext%20x%3D%22400%22%20y%3D%22310%22%20font-family%3D%22monospace%22%20font-size%3D%2228%22%20fill%3D%22%236f665a%22%20text-anchor%3D%22middle%22%3Eshabbat%20table%20photo%3C%2Ftext%3E%3C%2Fsvg%3E', 'מחר בערב בחדרה: תמיר חוזר הביתה לארוחת שישי – "סופר את השעות"', 'אחרי שבועות של מבחנים באוניברסיטת תל אביב, סטודנט הפסיכולוגיה בן ה-24 נוסע מחר להורים. "אני כבר מתגעגע לשולחן של שישי"', 'תמיר לוי חוזר מחר הביתה לחדרה לארוחת שישי', array['אחרי שבועות של מבחנים ולילות בספרייה באוניברסיטת תל אביב, תמיר, סטודנט לפסיכולוגיה בן 24, אורז תיק לסוף השבוע. בתוכו: כביסה, מחברת אחת שהוא עוד לא מוכן להיפרד ממנה, ומטען.', 'בתקופת המבחנים הוא כמעט לא יצא מהדירה, חוץ מלספרייה ולסופר. "אכלתי פסטה ארבעה ימים ברצף", הוא מספר. "בשלב מסוים התחלתי לחלום על השולחן של שישי".', '"אני כבר מתגעגע לשולחן של שישי", הוא אומר. "אני סופר את השעות עד שאני בבית". הוא מתכנן לעלות על הרכבת אחרי הצהריים, כדי להגיע לפני שכולם מתיישבים.', 'ההורים מחכים לו מחר בערב בחדרה. לפי תמיר, הוא כבר ביקש מראש את המנה האהובה עליו, "ואני מקווה שמישהו הקשיב".']::text[], null),
  ('o1', 'liat', now() - interval '5 hours', 'data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22800%22%20height%3D%22600%22%3E%3Cdefs%3E%3Cpattern%20id%3D%22p%22%20width%3D%2216%22%20height%3D%2216%22%20patternUnits%3D%22userSpaceOnUse%22%20patternTransform%3D%22rotate(45)%22%3E%3Crect%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23e6dfd1%22%2F%3E%3Crect%20x%3D%228%22%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23ddd5c5%22%2F%3E%3C%2Fpattern%3E%3C%2Fdefs%3E%3Crect%20width%3D%22800%22%20height%3D%22600%22%20fill%3D%22url(%23p)%22%2F%3E%3Ctext%20x%3D%22400%22%20y%3D%22310%22%20font-family%3D%22monospace%22%20font-size%3D%2228%22%20fill%3D%22%236f665a%22%20text-anchor%3D%22middle%22%3Ebalcony%20plants%20photo%3C%2Ftext%3E%3C%2Fsvg%3E', 'העגבנייה הראשונה במרפסת: ליאת קטפה את הפרי מהעציץ', '"חשבתי שהיונים יגיעו אליה קודם", היא מודה', 'עגבנייה ראשונה נקטפה במרפסת של ליאת', array['העציץ נשתל במרפסת של ליאת לפני חודשיים, כמעט במקרה. שתיל העגבנייה הגיע במתנה מהשכנה, וליאת, שמעולם לא גידלה כלום, שמה אותו בפינה הכי שמשית והתחילה להשקות.', 'בשבועות הראשונים הוא בעיקר גדל לגובה. אחר כך הופיעו פרחים צהובים קטנים, ואחריהם עגבנייה אחת ירוקה, שהלכה והאדימה לאט.', '"חשבתי שהיונים יגיעו אליה קודם", מודה ליאת. "כל בוקר יצאתי למרפסת לבדוק שהיא עוד שם. פעם אחת ראיתי יונה יושבת על המעקה ממש לידה, ופשוט נעמדתי שם עד שהיא עפה".', 'העגבנייה נקטפה הבוקר ונאכלה עם קצת מלח, עוד לפני ארוחת הבוקר. על השיח כבר יש שלוש חדשות.']::text[], null),
  ('o2', 'dudu', now() - interval '24 hours', 'data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22800%22%20height%3D%22600%22%3E%3Cdefs%3E%3Cpattern%20id%3D%22p%22%20width%3D%2216%22%20height%3D%2216%22%20patternUnits%3D%22userSpaceOnUse%22%20patternTransform%3D%22rotate(45)%22%3E%3Crect%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23e6dfd1%22%2F%3E%3Crect%20x%3D%228%22%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23ddd5c5%22%2F%3E%3C%2Fpattern%3E%3C%2Fdefs%3E%3Crect%20width%3D%22800%22%20height%3D%22600%22%20fill%3D%22url(%23p)%22%2F%3E%3Ctext%20x%3D%22400%22%20y%3D%22310%22%20font-family%3D%22monospace%22%20font-size%3D%2228%22%20fill%3D%22%236f665a%22%20text-anchor%3D%22middle%22%3Efootball%20photo%3C%2Ftext%3E%3C%2Fsvg%3E', 'השער שלא נשכח: דודו הבקיע בליגת השכונה מחצי מגרש', '"אף אחד לא האמין, גם לא אני", הוא אומר', 'דודו פרץ הבקיע מחצי מגרש בליגת השכונה', array['המשחק השבועי בליגת השכונה כמעט נגמר בתיקו. נשארו שתי דקות, שתי הקבוצות היו עייפות, ורוב השחקנים כבר חשבו על הבירה שאחרי.', 'הכדור הגיע לדודו באמצע המגרש, כשהשוער של היריבה עמד רחוק מהשער. "לא חשבתי בכלל", הוא מספר. "פשוט ראיתי שהשער פתוח ובעטתי".', 'הכדור עף מעל כולם ונחת ברשת. "אף אחד לא האמין, גם לא אני", אמר דודו. "לקח לי כמה שניות להבין שכולם רצים אליי".', 'הקבוצה ניצחה 3:2. מישהו מהספסל צילם את השער בטלפון, והסרטון כבר עבר בכל קבוצות הווטסאפ של השכונה.']::text[], null),
  ('o3', 'sharon', now() - interval '72 hours', 'data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22800%22%20height%3D%22600%22%3E%3Cdefs%3E%3Cpattern%20id%3D%22p%22%20width%3D%2216%22%20height%3D%2216%22%20patternUnits%3D%22userSpaceOnUse%22%20patternTransform%3D%22rotate(45)%22%3E%3Crect%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23e6dfd1%22%2F%3E%3Crect%20x%3D%228%22%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23ddd5c5%22%2F%3E%3C%2Fpattern%3E%3C%2Fdefs%3E%3Crect%20width%3D%22800%22%20height%3D%22600%22%20fill%3D%22url(%23p)%22%2F%3E%3Ctext%20x%3D%22400%22%20y%3D%22310%22%20font-family%3D%22monospace%22%20font-size%3D%2228%22%20fill%3D%22%236f665a%22%20text-anchor%3D%22middle%22%3Edog%20photo%3C%2Ftext%3E%3C%2Fsvg%3E', 'הכלבה של שרון למדה לתת כף – אחרי שבועיים של ניסיונות', '"ישבנו כל ערב עם חטיפים", היא מספרת', 'הכלבה של שרון למדה לתת כף', array['כבר שבועיים ששרון והכלבה שלה, בונה, מתאמנות כל ערב בסלון. המטרה הייתה אחת: שבונה תיתן כף.', 'בימים הראשונים בונה בעיקר ישבה, הסתכלה על החטיף ולא הבינה מה רוצים ממנה. "היא הציגה לי את כל הטריקים שהיא כבר יודעת, רק לא את זה", צוחקת שרון.', '"ישבנו כל ערב עם חטיפים", היא מספרת. "עשר דקות, לא יותר, כדי שלא תשתעמם". אתמול, באמצע האימון, בונה הרימה פתאום את הכף והניחה אותה בכף היד של שרון.', 'מאז היא נותנת כף לכל מי שנכנס הביתה, גם בלי שביקשו. "יצרתי מפלצת", אומרת שרון.']::text[], null),
  ('o4', 'avi', now() - interval '168 hours', 'data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22800%22%20height%3D%22600%22%3E%3Cdefs%3E%3Cpattern%20id%3D%22p%22%20width%3D%2216%22%20height%3D%2216%22%20patternUnits%3D%22userSpaceOnUse%22%20patternTransform%3D%22rotate(45)%22%3E%3Crect%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23e6dfd1%22%2F%3E%3Crect%20x%3D%228%22%20width%3D%228%22%20height%3D%2216%22%20fill%3D%22%23ddd5c5%22%2F%3E%3C%2Fpattern%3E%3C%2Fdefs%3E%3Crect%20width%3D%22800%22%20height%3D%22600%22%20fill%3D%22url(%23p)%22%2F%3E%3Ctext%20x%3D%22400%22%20y%3D%22310%22%20font-family%3D%22monospace%22%20font-size%3D%2228%22%20fill%3D%22%236f665a%22%20text-anchor%3D%22middle%22%3Esunrise%20photo%3C%2Ftext%3E%3C%2Fsvg%3E', 'הבוקר שבו אבי הגיע ראשון לחוף: "היה רק אני והים"', 'אחרי חודשים שבהם תכנן לקום מוקדם, השעון צלצל בחמש והוא קם', 'אבי חדד ראה זריחה בחוף אחרי חודשים של ניסיונות', array['חודשים תכנן אבי לקום מוקדם ולראות זריחה בחוף. בכל פעם כיוון שעון, ובכל פעם השעון צלצל והוא לחץ על נודניק.', 'השבוע זה השתנה. השעון צלצל בחמש, והוא קם. "לא חשבתי, פשוט לבשתי מה שהיה על הכיסא ויצאתי", הוא מספר.', 'כשהגיע לחוף עוד היה חושך, והחול היה קר. הוא ישב קרוב למים וחיכה. "היה רק אני והים", הוא מספר. "אחרי כמה דקות הגיע עוד בחור עם כלב, וזהו".', 'הוא נשאר עד שהשמש עלתה כולה, ואז הלך לקנות קפה. "עכשיו אני מבין למה אנשים עושים את זה", אמר. "אני לא בטוח שאעשה את זה כל שבוע, אבל אני אעשה את זה שוב".']::text[], null);
